public int findMinFibonacciNumbers(int k) {
    int fib1 = 0, fib2 = 1, fib = 1;
    while (fib < k) {
        int tmp = fib2;
        fib2 = fib;
        fib = fib1 + fib2;
        fib1 = tmp;
    }
    if (fib == k) {
        return 1;
    }
    int count = 2;
    while (fib - k > 0) {
        tmp = fib2;
        fib2 = fib;
        fib = fib1 + fib2;
        fib1 = tmp;
        count++;
    }
    return count;
